      ...(sendFloor ? { floor } : {}),
      ...(sendTerms ? { terms } : {}),
      ...gradeTerms,
      ...(sendLatePct ? { latePct } : {}),
      ...(sendPolicyDate ? { policyDate } : {}),
      ...(sendPeriodNumbering ? { periodNumberingFrom } : {}),
      ...(sendCap ? { cap } : {}),
