import { HttpClient } from '@angular/common/http';
import { DestroyRef, Injectable, computed, inject, signal } from '@angular/core';
import { Observable, map, tap } from 'rxjs';

interface User {
  name: string;
}

interface SheetView {
  id: string;
  today: string;
}

// Who is signed in and which sheet is active. Everything else in the app is kept per sheet, so
// features read `sheetId` and send `user` with their requests (the X-User header).
@Injectable({ providedIn: 'root' })
export class Session {
  private readonly http = inject(HttpClient);

  private readonly _user = signal<string | null>(null);
  private readonly _sheetId = signal<string | null>(null);
  readonly user = this._user.asReadonly();
  private readonly _today = signal<string | null>(null);
  readonly sheetId = this._sheetId.asReadonly();
  /** The active sheet's today (yyyy-mm-dd). Date-dependent features use this, never the clock. */
  readonly today = this._today.asReadonly();
  /** The features that read a sheet's data when it is loaded, and those still reading the active one's. */
  private readonly loaders = new Set<symbol>();
  private readonly pending = signal<ReadonlySet<symbol>>(new Set());
  /** The active sheet once every feature has read its data for it; null until then. */
  readonly loadedSheetId = computed(() => (this.pending().size === 0 ? this._sheetId() : null));

  /** Register a feature that reads each sheet's data when it is loaded, for as long as it lives; it calls the
   * function returned once it has read the data for a sheet id. One registered while a sheet is active is
   * still reading that sheet's. */
  registerLoader(destroyRef: DestroyRef): (sheetId: string | null) => void {
    const key = Symbol();
    this.loaders.add(key);
    if (this._sheetId() !== null) this.pending.update((p) => new Set([...p, key]));
    const settle = () => this.pending.update((p) => new Set([...p].filter((k) => k !== key)));
    destroyRef.onDestroy(() => {
      this.loaders.delete(key);
      settle();
    });
    return (sheetId) => {
      if (sheetId === this._sheetId()) settle();
    };
  }

  signIn(name: string): Observable<string> {
    return this.http.post<User>('/api/session', { name }).pipe(
      map((u) => u.name),
      tap((n) => {
        this._user.set(n);
        this.pending.set(new Set());
        this._sheetId.set(null);
        this._today.set(null);
      }),
    );
  }

  loadSheet(id: string): Observable<string> {
    return this.http
      .post<SheetView>('/api/sheets/load', { id }, { headers: { 'X-User': this._user() ?? '' } })
      .pipe(
        tap((s) => {
          this.pending.set(new Set(this.loaders));
          this._sheetId.set(s.id);
          this._today.set(s.today);
        }),
        map((s) => s.id),
      );
  }

  setToday(today: string): Observable<string> {
    const id = this._sheetId() ?? '';
    return this.http
      .put<SheetView>(
        `/api/sheets/${encodeURIComponent(id)}/today`,
        { today },
        { headers: { 'X-User': this._user() ?? '' } },
      )
      .pipe(
        tap((s) => {
          if (this._sheetId() === s.id) this._today.set(s.today);
        }),
        map((s) => s.today),
      );
  }
}
}

/** Only OPEN, PENDING and SETTLED claims count toward what is claimed and due. */
export function counts(claim: Claim): boolean {
  return isOpen(claim) || claim.status === 'SETTLED';
}

/** Whether a claim goes by the figure its person's last statement bound it to: a PENDING claim is not bound, but
 * shows its live figure. */
export function bound(claim: Claim): boolean {
  return claim.stated && claim.status !== 'PENDING';
}

/** What a claim's late charge goes by: the sheet's today and its late percent; and the policy date its
 * rounding goes by, the sheet's today when there is none. */
export interface Lateness {
  today: string | null;
  /** With two decimals, e.g. "10.00". */
  latePct: string;
  policyDate: string | null;
}

/** The date a claim's rounding goes by: a correction's is the date of the claim of its person's (`claims`) it
 * corrects, any other's its own. */
export function roundsBy(claim: Claim, claims: readonly Claim[]): string {
  if (claim.corrects === null) return claim.date;
  return claims.find((c) => c.number === claim.corrects)?.date ?? claim.date;
}

/** Whether a claim's live figures round half up: the date they go by is before the policy date. Otherwise
 * they round half to even. */
function roundsHalfUp(date: string, late: Lateness): boolean {
  return late.policyDate !== null && date < late.policyDate;
}

/** The days in each period an overdue claim gains the late percent for. */
const LATE_PERIOD_DAYS = 30;

/** A settled claim's due is the figure it was settled at (its late charge frozen in); a claim bound by its
 * person's last statement (and not PENDING) has the figure it was bound to; any other has the figure due at the rate `grade`, the
 * one its person has on the claim's date, has now in force on that date, and at least the sheet's floor (n/a
